def car_race_collision(n: int):
    positions = [0] * n
    directions = [1] * n  # 1 represents moving left to right, -1 represents moving right to left
    collisions = 0

    for i in range(n):
        for j in range(i + 1, n):
            if directions[i] != directions[j]:
                time_to_collision = (positions[j] - positions[i]) / (directions[i] - directions[j])
                if time_to_collision >= 0:
                    collisions += 1

    return collisions
